import React from "react";
import styled, { keyframes, css } from "styled-components";

const DiagramContainer = styled.div`
  position: relative;
`;

const rotate = keyframes`
  0% {
    transform: rotateY(0deg);
  }
  100% {
    transform: rotateY(360deg);
  }
`;

const Fan = styled.g`
  transform-origin: 1324px 680px;
  animation: ${(props) =>
    props.isrunning === "true"
      ? css`
          ${rotate} 1.2s linear infinite
        `
      : "none"};
`;

const ToggleSwitchContainer = styled.div`
  position: absolute;
  top: 54%;
  right: 3%;
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  user-select: none;

  .title {
    font-size: 24px;
    font-weight: bold;
    color: #00f1ff;
  }

  .switch {
    position: relative;
    display: inline-block;
    width: 90px;
    height: 40px;
    margin-top: 4px;

    input {
      opacity: 0;
      width: 0;
      height: 0;
    }

    .slider {
      position: absolute;
      cursor: pointer;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background-color: #ccc;
      transition: 0.4s;
      border-radius: 40px;

      &:before {
        position: absolute;
        content: "";
        height: 34px; /* 크기 증가 */
        width: 34px; /* 크기 증가 */
        left: 3px;
        bottom: 3px;
        background-color: white;
        transition: 0.4s;
        border-radius: 50%;
      }
    }

    input:checked + .slider {
      background-color: #2196f3;
    }

    input:checked + .slider:before {
      transform: translateX(46px); /* 가로 길이 증가에 맞게 조정 */
    }
  }

  .labels {
    display: flex;
    justify-content: space-between;
    width: 100px;
    margin-top: 3px;

    span {
      color: black; /* 검은색 적용 */
      font-weight: bold; /* 글자 굵게 */
    }
  }
`;
